package com.vuelossanitarios.backend.service;
import com.vuelossanitarios.backend.api.dto.AuditDtos.*;import com.vuelossanitarios.backend.domain.audit.AuditEvent;import com.vuelossanitarios.backend.domain.flight.Flight;import com.vuelossanitarios.backend.repository.*;import org.springframework.data.domain.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.util.*;
@Service public class AuditQueryService {private final AuditEventRepository events;private final FlightRepository flights;private final FlightAuthorizationService access;public AuditQueryService(AuditEventRepository e,FlightRepository f,FlightAuthorizationService a){events=e;flights=f;access=a;}@Transactional(readOnly=true)public AuditPage byFlight(UUID id,UUID user,int page,int size){Flight f=flights.findById(id).orElseThrow();access.mayRead(f,user);Page<AuditEvent> result=events.findByFlightIdOrderByOccurredAtDesc(id,paging(page,size));return page(result);}@Transactional(readOnly=true)public AuditPage all(int page,int size){return page(events.findAllByOrderByOccurredAtDesc(paging(page,size)));}private Pageable paging(int p,int s){return PageRequest.of(Math.max(0,p),Math.min(100,Math.max(1,s)));}private AuditPage page(Page<AuditEvent> p){return new AuditPage(p.getContent().stream().map(e->new AuditView(e.getId(),e.getFlight()==null?null:e.getFlight().getId(),e.getEntityType(),e.getEntityId(),e.getOperation(),e.getActor()==null?"sistema":e.getActor().getUsername(),e.getOccurredAt())).toList(),p.getTotalElements());}}
